import {
  users,
  topperProfiles,
  notes,
  reviewTasks,
  feedback,
  subscriptions,
  transactions,
  payouts,
  follows,
  downloads,
  notifications,
  noteViews,
  noteLikes,
  forumCategories,
  forumPosts,
  forumReplies,
  forumReplyLikes,
  coinPackages,
  broadcasts,
  userAchievements,
  dailyChallenges,
  userChallengeProgress,
  educationalCategories,
  userEducationalPreferences,
  withdrawalRequests,
  type User,
  type UpsertUser,
  type TopperProfile,
  type InsertTopperProfile,
  type Note,
  type InsertNote,
  type ReviewTask,
  type InsertReviewTask,
  type Feedback,
  type InsertFeedback,
  type Subscription,
  type InsertSubscription,
  type Transaction,
  type Payout,
  type Follow,
  type Download,
  type Notification,
  type NoteView,
  type InsertNoteView,
  type NoteLike,
  type InsertNoteLike,
  type ForumCategory,
  type InsertForumCategory,
  type ForumPost,
  type InsertForumPost,
  type ForumReply,
  type InsertForumReply,
  type ForumReplyLike,
  type CoinPackage,
  type InsertCoinPackage,
  type Broadcast,
  type InsertBroadcast,
  type UserAchievement,
  type InsertUserAchievement,
  type DailyChallenge,
  type InsertDailyChallenge,
  type UserChallengeProgress,
  type InsertUserChallengeProgress,
  type WithdrawalRequest,
  type InsertWithdrawalRequest,
} from "@shared/schema";
import { db } from "./db";
import { eq, desc, and, or, like, sql, count, avg, sum } from "drizzle-orm";

