  }

  .bg-pulse-danger {
    background: linear-gradient(135deg, #ef4444 0%, #f87171 50%, #fca5a5 100%);
    background-size: 400% 400%;
    animation: pulseGradient 3s ease-in-out infinite;
  }

  .bg-study-gradient {
    background: linear-gradient(45deg, #0f172a, #1e293b, #334155, #475569);
    background-size: 400% 400%;
    animation: studyFlow 8s ease-in-out infinite;
  }

  .bg-neon-glow {
    background: radial-gradient(circle at center, rgba(59, 130, 246, 0.1) 0%, transparent 70%);
    border: 1px solid rgba(59, 130, 246, 0.3);
    box-shadow: 0 0 30px rgba(59, 130, 246, 0.2), inset 0 1px 0 rgba(255, 255, 255, 0.1);
  }

  .bg-glass {
    background: rgba(255, 255, 255, 0.08);
    backdrop-filter: blur(16px);
    border: 1px solid rgba(255, 255, 255, 0.1);
  }

  /* Subject-specific colors */
  .subject-math { 
    background: linear-gradient(135deg, hsl(220, 100%, 85%) 0%, hsl(240, 100%, 90%) 100%);
    color: hsl(220, 100%, 25%);
  }

  .subject-physics { 
    background: linear-gradient(135deg, hsl(270, 100%, 85%) 0%, hsl(290, 100%, 90%) 100%);
    color: hsl(270, 100%, 25%);
  }

  .subject-chemistry { 
    background: linear-gradient(135deg, hsl(120, 100%, 85%) 0%, hsl(140, 100%, 90%) 100%);
    color: hsl(120, 100%, 25%);
  }

  .subject-biology { 
    background: linear-gradient(135deg, hsl(160, 100%, 85%) 0%, hsl(180, 100%, 90%) 100%);
    color: hsl(160, 100%, 25%);
  }

  .subject-computer { 
