    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(245, 100, 60, 0.6), 0 4px 12px rgba(245, 100, 60, 0.4);
  }

  /* Text Effects */
  .text-gradient {
    background: linear-gradient(135deg, hsl(245, 100%, 60%) 0%, hsl(270, 100%, 65%) 100%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    font-weight: 700;
  }

  .text-glow {
    text-shadow: 0 0 10px rgba(245, 100, 60, 0.5);
  }

  .gradient-primary {
    background: linear-gradient(135deg, hsl(213, 100%, 40%) 0%, hsl(25, 95%, 53%) 100%);
  }

  .gradient-secondary {
    background: linear-gradient(135deg, hsl(210, 40%, 96%) 0%, hsl(0, 0%, 100%) 100%);
  }

  .gradient-hero {
    background: linear-gradient(135deg, hsl(213, 100%, 40%) 0%, hsl(195, 100%, 45%) 50%, hsl(25, 95%, 53%) 100%);
  }

  .glass-effect {
    backdrop-filter: blur(12px);
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.2);
  }

  .hover-scale {
    transition: transform 0.2s ease-in-out;
  }

  .hover-scale:hover {
    transform: scale(1.05);
  }

  .hover-lift {
    transition: transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out;
  }

  .hover-lift:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.15);
  }

  .glow-effect {
    box-shadow: 0 0 20px rgba(59, 130, 246, 0.3);
  }

  .shimmer {
    background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%);
    background-size: 200% 100%;
    animation: shimmer 2s infinite;
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes bounceIn {
  0% {
    opacity: 0;
    transform: scale(0.3);
  }
  50% {
    transform: scale(1.1);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes shimmer {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

@keyframes float {
  0%, 100% {
    transform: translateY(0px);
  }
  50% {
    transform: translateY(-20px);
  }
}

@keyframes glow {
  0% {
    box-shadow: 0 0 10px rgba(255, 255, 255, 0.3);
  }
  100% {
    box-shadow: 0 0 20px rgba(255, 255, 255, 0.6), 0 0 30px rgba(255, 255, 255, 0.4);
