client/src/pages/note-detail.tsx.content:
import { useParams } from "wouter";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/useAuth";
import Header from "@/components/layout/header";
import Sidebar from "@/components/layout/sidebar";
import { MetaTags, generateNoteMetaTags } from "@/components/seo/meta-tags";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { 
  Download, 
  Star, 
  Heart, 
  Calendar, 
  User, 
  BookOpen, 
  GraduationCap,
  MessageSquare,
  AlertCircle,
  StarIcon
} from "lucide-react";
import { useState } from "react";
import { isUnauthorizedError } from "@/lib/authUtils";

interface NoteDetailParams {
  id: string;
}

export default function NoteDetail() {
  const { id } = useParams<NoteDetailParams>();
  const { user } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [rating, setRating] = useState(5);
  const [comment, setComment] = useState("");

  const { data: noteData, isLoading } = useQuery({
    queryKey: ["/api/notes", id],
    enabled: !!id,
    retry: false,
  });

  const downloadMutation = useMutation({
    mutationFn: async () => {
      await apiRequest("POST", `/api/notes/${id}/download`);
    },
    onSuccess: (data: any) => {
      toast({
        title: "Download Started",
        description: "Your note download has been recorded.",
      });
      // In a real app, this would trigger the actual file download
      console.log("Download URLs:", data.downloadUrl);
    },
    onError: (error: Error) => {
      if (isUnauthorizedError(error)) {
        toast({
          title: "Unauthorized",
          description: "You are logged out. Logging in again...",
          variant: "destructive",
        });
        setTimeout(() => {
          window.location.href = "/api/login";
        }, 500);
        return;
      }

      if (error.message.includes("subscription required")) {
        toast({
          title: "Subscription Required",
          description: "Please subscribe to download notes.",
          variant: "destructive",
        });
        // Redirect to subscription page
        window.location.href = "/subscribe";
        return;
      }

      toast({
        title: "Download Failed",
        description: error.message || "Failed to download note",
        variant: "destructive",
      });
    },
  });

  const feedbackMutation = useMutation({
    mutationFn: async () => {
      await apiRequest("POST", `/api/notes/${id}/feedback`, {
        rating,
        comment: comment.trim() || undefined,
      });
    },
    onSuccess: () => {
      toast({
        title: "Feedback Submitted",
        description: "Thank you for your feedback!",
      });
      setComment("");
      setRating(5);
      queryClient.invalidateQueries({ queryKey: ["/api/notes", id] });
    },
    onError: (error: Error) => {
      if (isUnauthorizedError(error)) {
        toast({
          title: "Unauthorized",
          description: "You are logged out. Logging in again...",
          variant: "destructive",
        });
        setTimeout(() => {
          window.location.href = "/api/login";
        }, 500);
        return;
      }
      toast({
        title: "Error",
        description: error.message || "Failed to submit feedback",
        variant: "destructive",
      });
    },
  });

  const followMutation = useMutation({
    mutationFn: async (topperId: string) => {
      await apiRequest("POST", `/api/follow/${topperId}`);
    },
    onSuccess: () => {
      toast({
        title: "Success",
        description: "You are now following this topper!",
      });
    },
    onError: (error: Error) => {
      if (isUnauthorizedError(error)) {
        toast({
          title: "Unauthorized",
          description: "You are logged out. Logging in again...",
          variant: "destructive",
        });
        setTimeout(() => {
          window.location.href = "/api/login";
        }, 500);
        return;
      }
      toast({
        title: "Error",
        description: error.message || "Failed to follow topper",
        variant: "destructive",
      });
    },
  });

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background">
        <Header />
        <div className="flex">
          <Sidebar />
          <main className="flex-1 p-6">
            <div className="flex items-center justify-center py-12">
              <div className="animate-spin w-8 h-8 border-4 border-primary border-t-transparent rounded-full" />
            </div>
          </main>
        </div>
      </div>
    );
  }

  if (!noteData) {
    return (
      <div className="min-h-screen bg-background">
        <Header />
        <div className="flex">
          <Sidebar />
          <main className="flex-1 p-6">
            <Card className="max-w-2xl mx-auto">
              <CardContent className="pt-6 text-center">
                <AlertCircle className="h-12 w-12 text-destructive mx-auto mb-4" />
                <h2 className="text-xl font-semibold mb-2">Note Not Found</h2>
                <p className="text-muted-foreground">
                  The note you're looking for doesn't exist or has been removed.
                </p>
              </CardContent>
            </Card>
          </main>
        </div>
      </div>
    );
  }

  const note = noteData as any;
  const averageRating = note?.feedback?.length > 0 
    ? note.feedback.reduce((sum: number, f: any) => sum + f.rating, 0) / note.feedback.length 
    : 0;

  // Generate SEO meta tags for this specific note
  const metaTags = generateNoteMetaTags(note);

  return (
    <div className="min-h-screen bg-background">
      <MetaTags {...metaTags} />
      <Header />
      <div className="flex">
        <Sidebar />
        <main className="flex-1 p-6">
          <div className="max-w-4xl mx-auto space-y-6">
            {/* Note Header */}
            <Card data-testid="note-header">
              <CardContent className="p-6">
                <div className="flex items-start justify-between mb-4">
                  <div className="flex-1">
                    <div className="flex items-center space-x-3 mb-2">
                      <h1 className="text-2xl font-bold text-foreground" data-testid="text-note-title">
                        {note.title}
                      </h1>
                      {note.featured && (
                        <Badge className="bg-green-100 text-green-800">Featured</Badge>
                      )}
                    </div>
                    <div className="flex items-center space-x-4 text-sm text-muted-foreground mb-3">
                      <span className="flex items-center space-x-1">
                        <BookOpen className="h-4 w-4" />
                        <span data-testid="text-note-subject">{note.subject}</span>
                      </span>
                      <span>•</span>
                      <span className="flex items-center space-x-1">
                        <GraduationCap className="h-4 w-4" />
                        <span data-testid="text-note-class">{note.classGrade}</span>
                      </span>
                      <span>•</span>
                      <span className="flex items-center space-x-1">
                        <Calendar className="h-4 w-4" />
                        <span>{new Date(note.publishedAt).toLocaleDateString()}</span>
                      </span>
                    </div>
                    {note.topic && (
                      <p className="text-sm text-muted-foreground mb-4">
                        <strong>Topic:</strong> {note.topic}
                      </p>
                    )}
                  </div>

                  <div className="flex space-x-2 ml-6">
                    <Button
                      onClick={() => downloadMutation.mutate()}
                      disabled={downloadMutation.isPending}
                      data-testid="button-download"
                    >
                      <Download className="h-4 w-4 mr-2" />
                      {downloadMutation.isPending ? "Downloading..." : "Download"}
                    </Button>
                    <Button variant="outline" data-testid="button-favorite">
                      <Heart className="h-4 w-4" />
                    </Button>
                  </div>
                </div>

                <p className="text-muted-foreground mb-6" data-testid="text-note-description">
                  {note.description}
                </p>

                {/* Note Stats */}
                <div className="flex items-center justify-between border-t border-border pt-4">
                  <div className="flex items-center space-x-6">
                    <div className="flex items-center space-x-1">
                      <div className="flex text-yellow-400">
                        {[1, 2, 3, 4, 5].map((star) => (
                          <StarIcon 
                            key={star} 
                            className={`h-4 w-4 ${
                              star <= averageRating ? 'fill-current' : ''
                            }`} 
                          />
                        ))}
                      </div>
                      <span className="text-sm text-muted-foreground" data-testid="text-average-rating">
                        {averageRating.toFixed(1)} ({note.feedback?.length || 0} reviews)
                      </span>
                    </div>
                    <span className="text-sm text-muted-foreground" data-testid="text-downloads-count">
                      <Download className="h-4 w-4 inline mr-1" />
                      {note.downloadsCount} downloads
                    </span>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Topper Info */}
            <Card data-testid="topper-info">
              <CardHeader>
                <CardTitle className="flex items-center space-x-2">
                  <User className="h-5 w-5" />
                  <span>About the Topper</span>
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="flex items-start justify-between">
                  <div className="flex items-center space-x-4">
                    <Avatar className="h-12 w-12">
                      <AvatarFallback className="bg-primary text-primary-foreground">
                        {note.topper?.firstName?.[0]}{note.topper?.lastName?.[0]}
                      </AvatarFallback>
                    </Avatar>
                    <div>
                      <h3 className="font-semibold text-foreground" data-testid="text-topper-name">
                        {note.topper?.firstName} {note.topper?.lastName}
                      </h3>
                      {note.topper?.topperProfile?.achievements && (
                        <p className="text-sm text-muted-foreground" data-testid="text-topper-achievements">
                          {note.topper.topperProfile.achievements}
                        </p>
                      )}
                      {note.topper?.topperProfile?.bio && (
                        <p className="text-sm text-muted-foreground mt-2">
                          {note.topper.topperProfile.bio}
                        </p>
                      )}
                    </div>
                  </div>

                  <Button
                    variant="outline"
                    onClick={() => followMutation.mutate(note.topperId)}
                    disabled={followMutation.isPending}
                    data-testid="button-follow-topper"
                  >
                    {followMutation.isPending ? "Following..." : "Follow"}
                  </Button>
                </div>
              </CardContent>
            </Card>

            {/* Feedback Section */}
            <Card data-testid="feedback-section">
              <CardHeader>
                <CardTitle className="flex items-center space-x-2">
                  <MessageSquare className="h-5 w-5" />
                  <span>Feedback & Reviews</span>
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-6">
                {/* Add Feedback Form */}
                {user && (
                  <div className="border border-border rounded-lg p-4" data-testid="feedback-form">
                    <h4 className="font-medium mb-4">Leave Your Feedback</h4>
                    <div className="space-y-4">
                      <div>
                        <label className="block text-sm font-medium mb-2">Rating</label>
                        <div className="flex items-center space-x-1">
                          {[1, 2, 3, 4, 5].map((star) => (
                            <StarIcon
                              key={star}
                              className={`h-6 w-6 cursor-pointer transition-colors ${
                                star <= rating 
                                  ? 'text-yellow-400 fill-current' 
                                  : 'text-gray-300'
                              }`}
                              onClick={() => setRating(star)}
                              data-testid={`star-${star}`}
                            />
                          ))}
                        </div>
                      </div>
                      <div>
                        <label className="block text-sm font-medium mb-2">Comment (Optional)</label>
                        <Textarea
                          value={comment}
                          onChange={(e) => setComment(e.target.value)}
                          placeholder="Share your thoughts about these notes..."
                          rows={3}
                          data-testid="textarea-feedback-comment"
                        />
                      </div>
                      <Button
                        onClick={() => feedbackMutation.mutate()}
                        disabled={feedbackMutation.isPending}
                        data-testid="button-submit-feedback"
                      >
                        {feedbackMutation.isPending ? "Submitting..." : "Submit Feedback"}
                      </Button>
                    </div>
                  </div>
                )}

                {/* Existing Feedback */}
                <div className="space-y-4" data-testid="feedback-list">
                  {note.feedback?.length > 0 ? (
                    note.feedback.map((feedback: any) => (
                      <div key={feedback.id} className="border border-border rounded-lg p-4">
                        <div className="flex items-start justify-between mb-2">
                          <div className="flex items-center space-x-3">
                            <Avatar className="h-8 w-8">
                              <AvatarFallback>
                                {feedback.student?.firstName?.[0]}{feedback.student?.lastName?.[0]}
                              </AvatarFallback>
                            </Avatar>
                            <div>
                              <p className="font-medium text-sm">
                                {feedback.student?.firstName} {feedback.student?.lastName}
                              </p>
                              <p className="text-xs text-muted-foreground">
                                {new Date(feedback.createdAt).toLocaleDateString()}
                              </p>
                            </div>
                          </div>
                          <div className="flex text-yellow-400">
                            {[1, 2, 3, 4, 5].map((star) => (
                              <StarIcon 
                                key={star} 
                                className={`h-4 w-4 ${
                                  star <= feedback.rating ? 'fill-current' : ''
                                }`} 
                              />
                            ))}
                          </div>
                        </div>
                        {feedback.comment && (
                          <p className="text-sm text-muted-foreground">{feedback.comment}</p>
                        )}
                      </div>
                    ))
                  ) : (
                    <div className="text-center py-8 text-muted-foreground">
                      <MessageSquare className="h-12 w-12 mx-auto mb-4 opacity-50" />
                      <p>No feedback yet. Be the first to review these notes!</p>
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>
          </div>
        </main>
      </div>
    </div>
  );
}

client/src/pages/review-queue.tsx.content:
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/useAuth";
import Header from "@/components/layout/header";
import Sidebar from "@/components/layout/sidebar";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { Clock, CheckCircle, Edit, TrendingUp, AlertCircle, FileText, User, X } from "lucide-react";
import { isUnauthorizedError } from "@/lib/authUtils";
import { useState } from "react";

export default function ReviewQueue() {
  const { user } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [rejectionComment, setRejectionComment] = useState("");
  const [rejectionDialogOpen, setRejectionDialogOpen] = useState(false);
  const [selectedTaskId, setSelectedTaskId] = useState("");

  // Check if user has admin permissions
  if (user && user.role !== 'admin') {
    return (
      <div className="min-h-screen bg-background">
        <Header />
        <div className="flex">
          <Sidebar />
          <main className="flex-1 p-6">
            <Card className="max-w-2xl mx-auto">
              <CardContent className="pt-6 text-center">
                <AlertCircle className="h-12 w-12 text-destructive mx-auto mb-4" />
                <h2 className="text-xl font-semibold mb-2">Access Restricted</h2>
                <p className="text-muted-foreground">
                  Only admin members can access the review queue for quality control.
                </p>
              </CardContent>
            </Card>
          </main>
        </div>
      </div>
    );
  }

  const { data: reviewTasks, isLoading } = useQuery({
    queryKey: ["/api/review/queue"],
    retry: false,
  });

  const approveMutation = useMutation({
    mutationFn: async (taskId: string) => {
      await apiRequest("PUT", `/api/review/${taskId}/approve`);
    },
    onSuccess: () => {
      toast({
        title: "Success",
        description: "Note approved and published successfully!",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/review/queue"] });
    },
    onError: (error: Error) => {
      if (isUnauthorizedError(error)) {
        toast({
          title: "Unauthorized",
          description: "You are logged out. Logging in again...",
          variant: "destructive",
        });
        setTimeout(() => {
          window.location.href = "/api/login";
        }, 500);
        return;
      }
      toast({
        title: "Error",
        description: error.message || "Failed to approve note",
        variant: "destructive",
      });
    },
  });

  const rejectMutation = useMutation({
    mutationFn: async ({ taskId, comments }: { taskId: string; comments: string[] }) => {
      await apiRequest("PUT", `/api/review/${taskId}/reject`, { comments });
    },
    onSuccess: () => {
      toast({
        title: "Success",
        description: "Note rejected with feedback sent to topper.",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/review/queue"] });
      setRejectionDialogOpen(false);
      setRejectionComment("");
      setSelectedTaskId("");
    },
    onError: (error: Error) => {
      if (isUnauthorizedError(error)) {
        toast({
          title: "Unauthorized",
          description: "You are logged out. Logging in again...",
          variant: "destructive",
        });
        setTimeout(() => {
          window.location.href = "/api/login";
        }, 500);
        return;
      }
      toast({
        title: "Error",
        description: error.message || "Failed to reject note",
        variant: "destructive",
      });
    },
  });

  const handleRejectClick = (taskId: string) => {
    setSelectedTaskId(taskId);
    setRejectionDialogOpen(true);
  };

  const handleRejectSubmit = () => {
    if (!rejectionComment.trim()) {
      toast({
        title: "Error",
        description: "Please provide a reason for rejection.",
        variant: "destructive",
      });
      return;
    }

    rejectMutation.mutate({ 
      taskId: selectedTaskId, 
      comments: [rejectionComment.trim()] 
    });
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'open':
        return <Badge variant="secondary" className="bg-yellow-100 text-yellow-800">Pending</Badge>;
      case 'changes_requested':
        return <Badge variant="secondary" className="bg-orange-100 text-orange-800">Changes Requested</Badge>;
      case 'approved':
        return <Badge variant="secondary" className="bg-green-100 text-green-800">Approved</Badge>;
      case 'rejected':
        return <Badge variant="destructive">Rejected</Badge>;
      default:
        return <Badge variant="outline">{status}</Badge>;
    }
  };

  return (
    <div className="min-h-screen bg-background">
      <Header />
      <div className="flex">
        <Sidebar />
        <main className="flex-1 p-6">
          <div className="mb-8">
            <h1 className="text-3xl font-bold text-foreground mb-2" data-testid="text-review-title">
              Review Queue
            </h1>
            <p className="text-muted-foreground" data-testid="text-review-description">
              Review and approve submitted notes from toppers
            </p>
          </div>

          {/* Review Stats */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
            <Card data-testid="card-pending-reviews">
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm font-medium text-muted-foreground">Pending Review</p>
                    <p className="text-2xl font-bold text-foreground">
                      {reviewTasks?.filter((task: any) => task.status === 'open').length || 0}
                    </p>
                  </div>
                  <Clock className="h-8 w-8 text-secondary" />
                </div>
              </CardContent>
            </Card>

            <Card data-testid="card-approved-today">
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm font-medium text-muted-foreground">Approved Today</p>
                    <p className="text-2xl font-bold text-green-600">
                      {reviewTasks?.filter((task: any) => 
                        task.status === 'approved' && 
                        new Date(task.decidedAt).toDateString() === new Date().toDateString()
                      ).length || 0}
                    </p>
                  </div>
                  <CheckCircle className="h-8 w-8 text-green-600" />
                </div>
              </CardContent>
            </Card>

            <Card data-testid="card-changes-requested">
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm font-medium text-muted-foreground">Changes Requested</p>
                    <p className="text-2xl font-bold text-orange-600">
                      {reviewTasks?.filter((task: any) => task.status === 'changes_requested').length || 0}
                    </p>
                  </div>
                  <Edit className="h-8 w-8 text-orange-600" />
                </div>
              </CardContent>
            </Card>

            <Card data-testid="card-avg-review-time">
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm font-medium text-muted-foreground">Avg Review Time</p>
                    <p className="text-2xl font-bold text-foreground">2.3h</p>
                  </div>
                  <TrendingUp className="h-8 w-8 text-primary" />
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Review Queue List */}
          <Card>
            <CardHeader>
              <CardTitle>Submitted Notes</CardTitle>
            </CardHeader>
            <CardContent className="p-0">
              {isLoading ? (
                <div className="flex items-center justify-center py-12">
                  <div className="animate-spin w-8 h-8 border-4 border-primary border-t-transparent rounded-full" />
                </div>
              ) : reviewTasks?.length > 0 ? (
                <div className="divide-y divide-border">
                  {reviewTasks.map((task: any) => (
                    <div 
                      key={task.id} 
                      className="p-6 hover:bg-accent transition-colors"
                      data-testid={`review-task-${task.id}`}
                    >
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <div className="flex items-center space-x-3 mb-2">
                            <h3 className="text-lg font-semibold text-foreground">
                              {task.note?.title || 'Untitled Note'}
                            </h3>
                            {getStatusBadge(task.status)}
                          </div>

                          <div className="flex items-center space-x-4 text-sm text-muted-foreground mb-3">
                            <span>{task.note?.subject} • {task.note?.classGrade}</span>
                            <span>•</span>
                            <span>Submitted {new Date(task.createdAt).toLocaleDateString()}</span>
                            <span>•</span>
                            <span>by {task.note?.topper?.firstName} {task.note?.topper?.lastName}</span>
                          </div>

                          <p className="text-muted-foreground text-sm mb-4">
                            {task.note?.description || 'No description provided'}
                          </p>

                          <div className="flex items-center space-x-4">
                            <span className="text-sm text-muted-foreground flex items-center">
                              <FileText className="h-4 w-4 mr-1" />
                              {task.note?.attachments?.length || 0} files
                            </span>
                            <span className="text-sm text-muted-foreground flex items-center">
                              <User className="h-4 w-4 mr-1" />
                              Topper Rating: {task.note?.topper?.topperProfile?.ratingAvg || 'N/A'}/5
                            </span>
                          </div>
                        </div>

                        <div className="flex space-x-2 ml-6">
                          {task.status === 'open' && (
                            <>
                              <Button
                                onClick={() => approveMutation.mutate(task.id)}
                                disabled={approveMutation.isPending}
                                data-testid={`button-approve-${task.id}`}
                              >
                                {approveMutation.isPending ? "Approving..." : "Approve"}
                              </Button>
                              <Dialog>
                                <DialogTrigger asChild>
                                  <Button
                                    variant="outline"
                                    onClick={() => handleRejectClick(task.id)}
                                    disabled={rejectMutation.isPending}
                                    data-testid={`button-reject-${task.id}`}
                                  >
                                    <X className="h-4 w-4 mr-1" />
                                    Reject
                                  </Button>
                                </DialogTrigger>
                                <DialogContent className="sm:max-w-md">
                                  <DialogHeader>
                                    <DialogTitle>Reject Note - Provide Reason</DialogTitle>
                                  </DialogHeader>
                                  <div className="space-y-4">
                                    <div>
                                      <label className="text-sm font-medium">
                                        Reason for rejection (will be sent to the topper):
                                      </label>
                                      <Textarea
                                        value={rejectionComment}
                                        onChange={(e) => setRejectionComment(e.target.value)}
                                        placeholder="Please provide specific feedback on what needs to be improved..."
                                        className="mt-2"
                                        rows={4}
                                        data-testid="textarea-rejection-comment"
                                      />
                                    </div>
                                    <div className="flex justify-end space-x-2">
                                      <Button
                                        variant="outline"
                                        onClick={() => {
                                          setRejectionDialogOpen(false);
                                          setRejectionComment("");
                                          setSelectedTaskId("");
                                        }}
                                      >
                                        Cancel
                                      </Button>
                                      <Button
                                        onClick={handleRejectSubmit}
                                        disabled={rejectMutation.isPending || !rejectionComment.trim()}
                                        className="bg-red-600 hover:bg-red-700"
                                        data-testid="button-confirm-reject"
                                      >
                                        {rejectMutation.isPending ? "Rejecting..." : "Reject Note"}
                                      </Button>
                                    </div>
                                  </div>
                                </DialogContent>
                              </Dialog>
                            </>
                          )}
                          <Button 
                            variant="outline"
                            data-testid={`button-preview-${task.id}`}
                          >
                            Preview
                          </Button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-12" data-testid="empty-review-queue">
                  <Clock className="h-12 w-12 text-muted-foreground mx-auto mb-4 opacity-50" />
                  <h3 className="text-lg font-medium text-foreground mb-2">No pending reviews</h3>
                  <p className="text-sm text-muted-foreground">
                    All submitted notes have been reviewed
                  </p>
                </div>
              )}
            </CardContent>
          </Card>
        </main>
      </div>
    </div>
  );
}

client/src/pages/subscribe.tsx.content:
import { useStripe, Elements, PaymentElement, useElements } from '@stripe/react-stripe-js';
import { loadStripe } from '@stripe/stripe-js';
import { useEffect, useState } from 'react';
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { useAuth } from "@/hooks/useAuth";
import Header from "@/components/layout/header";
import { CheckCircle, Crown } from "lucide-react";

// Stripe is optional - only initialize if key is provided
const stripePromise = import.meta.env.VITE_STRIPE_PUBLIC_KEY 
  ? loadStripe(import.meta.env.VITE_STRIPE_PUBLIC_KEY)
  : Promise.resolve(null);

const SubscribeForm = ({ plan }: { plan: string }) => {
  const stripe = useStripe();
  const elements = useElements();
  const { toast } = useToast();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!stripe || !elements) {
      return;
    }

    const { error } = await stripe.confirmPayment({
      elements,
      confirmParams: {
        return_url: window.location.origin,
      },
    });

    if (error) {
      toast({
        title: "Payment Failed",
        description: error.message,
        variant: "destructive",
      });
    } else {
      toast({
        title: "Payment Successful",
        description: "You are now subscribed to MasterStudent Premium!",
      });
    }
  }

  return (
    <form onSubmit={handleSubmit} data-testid="form-subscription">
      <PaymentElement />
      <Button 
        type="submit" 
        className="w-full mt-6" 
        disabled={!stripe || !elements}
        data-testid="button-submit-payment"
      >
        Subscribe Now
      </Button>
    </form>
  );
};

export default function Subscribe() {
  const [clientSecret, setClientSecret] = useState("");
  const [selectedPlan, setSelectedPlan] = useState("");
  const [loading, setLoading] = useState(false);
  const { user } = useAuth();
  const { toast } = useToast();

  const createSubscription = async (plan: string) => {
    setLoading(true);
    try {
      const response = await apiRequest("POST", "/api/create-subscription", { plan });
      const data = await response.json();
      if (response.status === 503) {
        toast({
          title: "Payment Unavailable",
          description: "Payment processing is currently not configured. Please contact support.",
          variant: "destructive",
        });
        return;
      }
      setClientSecret(data.clientSecret);
    } catch (error: any) {
      toast({
        title: "Error",
        description: error.message || "Failed to create subscription",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  if (!clientSecret) {
    return (
      <div className="min-h-screen bg-background">
        <Header />
        <div className="max-w-4xl mx-auto p-6">
          <div className="text-center mb-8">
            <Crown className="h-16 w-16 text-secondary mx-auto mb-4" />
            <h1 className="text-3xl font-bold text-foreground mb-2" data-testid="text-upgrade-title">
              Upgrade to Premium
            </h1>
            <p className="text-muted-foreground" data-testid="text-upgrade-description">
              Access unlimited downloads and premium content
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
            <Card 
              className={`cursor-pointer transition-colors ${
                selectedPlan === 'monthly' ? 'border-primary border-2' : ''
              }`}
              onClick={() => setSelectedPlan('monthly')}
              data-testid="card-monthly-plan"
            >
              <CardHeader>
                <CardTitle className="flex items-center justify-between">
                  Monthly Plan
                  <div className="text-right">
                    <span className="text-2xl font-bold text-foreground">₹59</span>
                    <p className="text-sm text-muted-foreground">/month</p>
                  </div>
                </CardTitle>
              </CardHeader>
              <CardContent>
                <p className="text-sm text-muted-foreground mb-4">Perfect for short-term needs</p>
                <div className="space-y-2">
                  <div className="flex items-center space-x-2">
                    <CheckCircle className="h-4 w-4 text-green-500" />
                    <span className="text-sm">Unlimited note downloads</span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <CheckCircle className="h-4 w-4 text-green-500" />
                    <span className="text-sm">Access to all subjects</span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <CheckCircle className="h-4 w-4 text-green-500" />
                    <span className="text-sm">Follow toppers</span>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card 
              className={`cursor-pointer transition-colors relative ${
                selectedPlan === 'yearly' ? 'border-primary border-2' : ''
              }`}
              onClick={() => setSelectedPlan('yearly')}
              data-testid="card-yearly-plan"
            >
              <div className="absolute -top-3 left-1/2 transform -translate-x-1/2 bg-gradient-to-r from-orange-500 to-red-500 text-white px-4 py-1 rounded-full text-sm font-bold shadow-lg z-10">
                MOST POPULAR
              </div>
              <CardHeader>
                <CardTitle className="flex items-center justify-between">
                  Yearly Plan
                  <div className="text-right">
                    <span className="text-2xl font-bold text-foreground">₹499</span>
                    <p className="text-sm text-muted-foreground">/year</p>
                    <p className="text-xs text-green-600">Save ₹209</p>
                  </div>
                </CardTitle>
              </CardHeader>
              <CardContent>
                <p className="text-sm text-muted-foreground mb-4">Save 30% with annual billing</p>
                <div className="space-y-2">
                  <div className="flex items-center space-x-2">
                    <CheckCircle className="h-4 w-4 text-green-500" />
                    <span className="text-sm">Everything in Monthly</span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <CheckCircle className="h-4 w-4 text-green-500" />
                    <span className="text-sm">Priority support</span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <CheckCircle className="h-4 w-4 text-green-500" />
                    <span className="text-sm">Early access to features</span>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>

          <div className="text-center">
            <Button 
              size="lg" 
              onClick={() => createSubscription(selectedPlan)}
              disabled={loading || !selectedPlan}
              data-testid="button-proceed-payment"
            >
              {loading 
                ? "Processing..." 
                : !selectedPlan 
                ? "Select a Plan" 
                : `Subscribe to ${selectedPlan === 'yearly' ? 'Yearly' : 'Monthly'} Plan`
              }
            </Button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      <Header />
      <div className="max-w-md mx-auto p-6">
        <Card>
          <CardHeader>
            <CardTitle className="text-center">Complete Your Subscription</CardTitle>
          </CardHeader>
          <CardContent>
            <Elements stripe={stripePromise} options={{ clientSecret }}>
              <SubscribeForm plan={selectedPlan} />
            </Elements>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

