import { useAuth } from "@/hooks/useAuth";
import { Link, useLocation } from "wouter";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { 
  BookOpen, 
  Download, 
  Heart, 
  Plus, 
  FileText, 
  BarChart3, 
  ClipboardList, 
  Users, 
  Settings,
  Crown,
  User,
  LogOut
} from "lucide-react";

export default function Sidebar() {
  const { user } = useAuth();
  const [location] = useLocation();

  if (!user) {
    return null;
  }

  const isActive = (path: string) => location === path;

  const handleSignOut = async () => {
    try {
      await fetch('/api/logout', { method: 'POST' });
      window.location.href = '/';
    } catch (error) {
      console.error('Sign out error:', error);
      // Fallback - redirect anyway
      window.location.href = '/';
    }
  };

  const studentLinks = [
    { path: "/catalog", icon: BookOpen, label: "Browse Notes", active: isActive("/catalog") || isActive("/") },
    { path: "/downloads", icon: Download, label: "My Downloads", active: isActive("/downloads") },
    { path: "/following", icon: Heart, label: "Following", active: isActive("/following") },
    { path: "/profile", icon: User, label: "My Profile", active: isActive("/profile") },
  ];

  const topperLinks = [
    { path: "/upload", icon: Plus, label: "Upload Notes", active: isActive("/upload") },
    { path: "/my-notes", icon: FileText, label: "My Notes", active: isActive("/my-notes") },
    { path: "/analytics", icon: BarChart3, label: "Analytics", active: isActive("/analytics") },
  ];

  const reviewerLinks = [
    { path: "/review-queue", icon: ClipboardList, label: "Review Queue", active: isActive("/review-queue") },
  ];

  const adminLinks = [
    { path: "/admin", icon: Settings, label: "Dashboard", active: isActive("/admin") },
    { path: "/user-management", icon: Users, label: "User Management", active: isActive("/user-management") },
  ];

  return (
    <aside className="w-64 bg-card border-r border-border flex-shrink-0 sidebar-transition" data-testid="sidebar">
      <div className="p-6">
        <div className="space-y-6">
          {/* Student Portal */}
          <div>
            <h3 className="text-sm font-medium text-muted-foreground uppercase tracking-wider mb-3">
              Student Portal
            </h3>
            <nav className="space-y-2">
              {studentLinks.map((link) => (
                <Link 
                  key={link.path} 
                  href={link.path}
                  className={`flex items-center space-x-3 px-3 py-2 rounded-md transition-colors ${
                    link.active 
                      ? 'bg-primary text-primary-foreground' 
                      : 'hover:bg-accent text-foreground'
                  }`}
                  data-testid={`sidebar-link-${link.label.toLowerCase().replace(/\s+/g, '-')}`}
                >
                  <link.icon className="h-4 w-4" />
                  <span className="text-sm font-medium">{link.label}</span>
                </Link>
              ))}
            </nav>
          </div>

          {/* Topper Studio */}
          {(user.role === 'topper' || user.role === 'admin') && (
            <div>
              <h3 className="text-sm font-medium text-muted-foreground uppercase tracking-wider mb-3">
                Topper Studio
              </h3>
              <nav className="space-y-2">
                {topperLinks.map((link) => (
                  <Link 
                    key={link.path} 
                    href={link.path}
                    className={`flex items-center space-x-3 px-3 py-2 rounded-md transition-colors ${
                      link.active 
                        ? 'bg-primary text-primary-foreground' 
                        : 'hover:bg-accent text-foreground'
                    }`}
                    data-testid={`sidebar-topper-${link.label.toLowerCase().replace(/\s+/g, '-')}`}
                  >
                    <link.icon className="h-4 w-4" />
                    <span className="text-sm font-medium">{link.label}</span>
                  </Link>
                ))}
              </nav>
            </div>
          )}

          {/* Review/Admin */}
          {(user.role === 'reviewer' || user.role === 'admin') && (
            <div>
              <h3 className="text-sm font-medium text-muted-foreground uppercase tracking-wider mb-3">
                {user.role === 'admin' ? 'Admin' : 'Review'}
              </h3>
              <nav className="space-y-2">
                {/* Review Queue for both reviewers and admins */}
                <Link 
                  href="/review-queue"
                  className={`flex items-center space-x-3 px-3 py-2 rounded-md transition-colors ${
                    isActive('/review-queue') 
                      ? 'bg-primary text-primary-foreground' 
                      : 'hover:bg-accent text-foreground'
                  }`}
                  data-testid="sidebar-link-review-queue"
                >
                  <ClipboardList className="h-4 w-4" />
                  <span className="text-sm font-medium">Review Queue</span>
                  <Badge variant="secondary" className="ml-auto bg-secondary text-secondary-foreground text-xs px-2 py-1 rounded-full">
                    3
                  </Badge>
                </Link>

                {/* Admin-only links */}
                {user.role === 'admin' && adminLinks.map((link) => (
                  <Link 
                    key={link.path} 
                    href={link.path}
                    className={`flex items-center space-x-3 px-3 py-2 rounded-md transition-colors ${
                      link.active 
                        ? 'bg-primary text-primary-foreground' 
                        : 'hover:bg-accent text-foreground'
                    }`}
                    data-testid={`sidebar-admin-${link.label.toLowerCase().replace(/\s+/g, '-')}`}
                  >
                    <link.icon className="h-4 w-4" />
                    <span className="text-sm font-medium">{link.label}</span>
                  </Link>
                ))}
              </nav>
            </div>
          )}

          {/* Subscription Upgrade */}
          {user.role === 'student' && (
            <div className="pt-6 border-t border-border">
              <Link 
                href="/subscribe"
                className="flex items-center space-x-3 px-3 py-2 rounded-md bg-gradient-to-r from-primary to-secondary text-primary-foreground hover:opacity-90 transition-opacity"
                data-testid="sidebar-link-upgrade"
              >
                <Crown className="h-4 w-4" />
                <span className="text-sm font-medium">Upgrade to Premium</span>
              </Link>
            </div>
          )}

          {/* User Role Display */}
          <div className="pt-6 border-t border-border">
            <div className="px-3 py-2 bg-muted rounded-md">
              <p className="text-xs text-muted-foreground">Signed in as</p>
              <p className="text-sm font-medium text-foreground">
                {user.firstName} {user.lastName}
              </p>
              <Badge 
                variant={user.role === 'admin' ? 'destructive' : 'secondary'}
                className="mt-1 text-xs"
                data-testid="sidebar-user-role"
              >
                {user.role.charAt(0).toUpperCase() + user.role.slice(1)}
              </Badge>
            </div>

            {/* Sign Out Button */}
            <Button
              variant="outline"
              size="sm"
              onClick={handleSignOut}
              className="mt-3 w-full flex items-center space-x-2 text-muted-foreground hover:text-foreground border-border hover:border-red-300 hover:bg-red-50"
              data-testid="button-sign-out"
            >
              <LogOut className="h-4 w-4" />
              <span>Sign Out</span>
            </Button>
          </div>
        </div>
      </div>
    </aside>
  );
}

client/src/components/notes/note-card.ts.content:
import { Link } from "wouter";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { 
  Download, 
  Star, 
  Clock, 
  Heart,
  StarIcon,
  TrendingUp,
  Award,
  Eye,
  BookOpen,
  MessageCircle,
  ThumbsUp
} from "lucide-react";
import { Note } from "@shared/schema";

// Helper function to get subject colors
const getSubjectColor = (subject: string) => {
  const colors: { [key: string]: string } = {
    'Mathematics': 'bg-blue-100 text-blue-800',
    'Physics': 'bg-purple-100 text-purple-800',
    'Chemistry': 'bg-green-100 text-green-800',
    'Biology': 'bg-emerald-100 text-emerald-800',
    'Computer Science': 'bg-gray-100 text-gray-800',
    'English': 'bg-red-100 text-red-800',
    'History': 'bg-amber-100 text-amber-800',
    'Geography': 'bg-cyan-100 text-cyan-800',
    'Economics': 'bg-yellow-100 text-yellow-800',
    'Political Science': 'bg-indigo-100 text-indigo-800'
  };
  return colors[subject] || 'bg-gray-100 text-gray-800';
};

// Helper function to get subject icons
const getSubjectIcon = (subject: string) => {
  const icons: { [key: string]: string } = {
    'Mathematics': '📐',
    'Physics': '⚛️',
    'Chemistry': '🧪',
    'Biology': '🧬',
    'Computer Science': '💻',
    'English': '📚',
    'History': '📜',
    'Geography': '🌍',
    'Economics': '💰',
    'Political Science': '🏛️'
  };
  return icons[subject] || '📖';
};

interface NoteCardProps {
  note: Note;
  viewMode?: "grid" | "list";
}

export default function NoteCard({ note, viewMode = "grid" }: NoteCardProps) {
  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffTime = Math.abs(now.getTime() - date.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays === 1) return '1 day ago';
    if (diffDays < 7) return `${diffDays} days ago`;
    if (diffDays < 30) return `${Math.floor(diffDays / 7)} weeks ago`;
    return date.toLocaleDateString();
  };

  const getInitials = (name: string) => {
    return name.split(' ').map(n => n[0]).join('').toUpperCase();
  };

  if (viewMode === "list") {
    return (
      <Card className="note-card hover:shadow-md transition-all duration-200" data-testid={`note-card-${note.id}`}>
        <CardContent className="p-6">
          <div className="flex items-start justify-between">
            <div className="flex-1">
              <div className="flex items-start justify-between mb-3">
                <div className="flex-1">
                  <Link 
                    href={`/notes/${note.id}`}
                    className="text-lg font-semibold text-foreground hover:text-primary transition-colors"
                    data-testid="link-note-title"
                  >
                    {note.title}
                  </Link>
                  <div className="flex items-center space-x-4 text-sm text-muted-foreground mt-1">
                    <span data-testid="text-note-subject">{note.subject}</span>
                    <span>•</span>
                    <span data-testid="text-note-class">{note.classGrade}</span>
                  </div>
                </div>
                <div className="flex items-center space-x-2 ml-4">
                  {note.featured && (
                    <Badge className="bg-green-100 text-green-800">Featured</Badge>
                  )}
                  <Button size="sm" data-testid="button-favorite">
                    <Heart className="h-4 w-4" />
                  </Button>
                </div>
              </div>

              <p className="text-muted-foreground text-sm mb-4 line-clamp-2" data-testid="text-note-description">
                {note.description}
              </p>

              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-6">
                  <div className="flex items-center space-x-2">
                    <Avatar className="h-6 w-6">
                      <AvatarFallback className="bg-primary text-primary-foreground text-xs">
                        {getInitials(note.topperId || 'U')}
                      </AvatarFallback>
                    </Avatar>
                    <span className="text-sm font-medium text-foreground" data-testid="text-topper-name">
                      Anonymous Student
                    </span>
                  </div>

                  <div className="flex items-center space-x-1">
                    <div className="flex text-gray-300">
                      {[1, 2, 3, 4, 5].map((star) => (
                        <StarIcon key={star} className="h-3 w-3" />
                      ))}
                    </div>
                    <span className="text-xs text-muted-foreground">Not rated</span>
                  </div>

                  <span className="text-xs text-muted-foreground" data-testid="text-downloads-count">
                    <Download className="h-3 w-3 inline mr-1" />
                    {note.downloadsCount} downloads
                  </span>

                  <span className="text-xs text-muted-foreground">
                    <Clock className="h-3 w-3 inline mr-1" />
                    {formatDate((note.publishedAt || note.createdAt || new Date()).toString())}
                  </span>
                </div>

                <Button size="sm" asChild data-testid="button-view-note">
                  <Link href={`/notes/${note.id}`}>
                    View Details
                  </Link>
                </Button>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  // Grid view (default)
  return (
    <Card className="card-enhanced hover-lift transition-all duration-300 group relative overflow-hidden" data-testid={`note-card-${note.id}`}>
      {/* Gradient overlay for featured notes */}
      {note.featured && (
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-yellow-400 to-orange-500"></div>
      )}

      <CardContent className="p-6">
        {/* Header with badges */}
        <div className="flex items-start justify-between mb-4">
          <div className="flex items-center gap-2">
            <Badge className={`${getSubjectColor(note.subject)} hover-scale`}>
              <span className="mr-1">{getSubjectIcon(note.subject)}</span>
              {note.subject}
            </Badge>
            {note.featured && (
              <Badge className="bg-gradient-to-r from-yellow-400 to-orange-500 text-white animate-pulse-slow">
                <Award className="h-3 w-3 mr-1" />
                Featured
              </Badge>
            )}
          </div>
          <Button 
            variant="ghost" 
            size="sm" 
