import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/useAuth";
import Header from "@/components/layout/header";
import Sidebar from "@/components/layout/sidebar";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { AlertCircle, Upload, Wallet, FileText, TrendingUp, IndianRupee, Clock, CheckCircle, X } from "lucide-react";
import { isUnauthorizedError } from "@/lib/authUtils";
import { useState } from "react";

export default function UploaderProfile() {
  const { user } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [withdrawalDialogOpen, setWithdrawalDialogOpen] = useState(false);
  const [withdrawalAmount, setWithdrawalAmount] = useState("");
  const [paymentMethod, setPaymentMethod] = useState("upi");
  const [upiId, setUpiId] = useState("");
  const [bankDetails, setBankDetails] = useState({
    accountNumber: "",
    ifscCode: "",
    bankName: "",
    accountHolderName: "",
  });

  // Check if user is topper or admin
  if (user && user.role !== 'topper' && user.role !== 'admin') {
    return (
      <div className="min-h-screen bg-background">
        <Header />
        <div className="flex">
          <Sidebar />
          <main className="flex-1 p-6">
            <Card className="max-w-2xl mx-auto">
              <CardContent className="pt-6 text-center">
                <AlertCircle className="h-12 w-12 text-destructive mx-auto mb-4" />
                <h2 className="text-xl font-semibold mb-2">Access Restricted</h2>
                <p className="text-muted-foreground">
                  Only toppers can access the uploader profile.
                </p>
              </CardContent>
            </Card>
          </main>
        </div>
      </div>
    );
  }

  // Fetch uploader stats
  const { data: uploaderStats, isLoading } = useQuery({
    queryKey: ['/api/uploader/stats'],
    retry: false,
  });

  // Fetch withdrawal requests
  const { data: withdrawalRequests } = useQuery({
    queryKey: ['/api/withdrawals'],
    retry: false,
  });

  const withdrawalMutation = useMutation({
    mutationFn: async (withdrawalData: any) => {
      await apiRequest("POST", "/api/withdrawals/request", withdrawalData);
    },
    onSuccess: () => {
      toast({
        title: "Success",
        description: "Withdrawal request submitted successfully!",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/withdrawals"] });
      queryClient.invalidateQueries({ queryKey: ["/api/uploader/stats"] });
      setWithdrawalDialogOpen(false);
      setWithdrawalAmount("");
      setUpiId("");
      setBankDetails({
        accountNumber: "",
        ifscCode: "",
        bankName: "",
        accountHolderName: "",
      });
    },
    onError: (error: Error) => {
      if (isUnauthorizedError(error)) {
        toast({
          title: "Unauthorized",
          description: "You are logged out. Logging in again...",
          variant: "destructive",
        });
        setTimeout(() => {
          window.location.href = "/api/login";
        }, 500);
        return;
      }
      toast({
        title: "Error",
        description: error.message || "Failed to submit withdrawal request",
        variant: "destructive",
      });
    },
  });

  const handleWithdrawalSubmit = () => {
    const amount = parseFloat(withdrawalAmount);

    if (!amount || amount < 200) {
      toast({
        title: "Error",
        description: "Minimum withdrawal amount is ₹200",
        variant: "destructive",
      });
      return;
    }

    if (uploaderStats && amount > uploaderStats.walletBalance) {
      toast({
        title: "Error",
        description: "Insufficient wallet balance",
        variant: "destructive",
      });
      return;
    }

    const withdrawalData: any = {
      amount,
      coins: Math.floor(amount * 20), // Assuming 1 rupee = 20 coins
    };

    if (paymentMethod === "upi") {
      if (!upiId.trim()) {
        toast({
          title: "Error",
          description: "Please provide UPI ID",
          variant: "destructive",
        });
        return;
      }
      withdrawalData.upiId = upiId.trim();
    } else {
      if (!bankDetails.accountNumber || !bankDetails.ifscCode || !bankDetails.bankName || !bankDetails.accountHolderName) {
        toast({
          title: "Error",
          description: "Please fill all bank details",
          variant: "destructive",
        });
        return;
      }
      withdrawalData.bankDetails = bankDetails;
    }

    withdrawalMutation.mutate(withdrawalData);
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'pending':
        return <Badge variant="secondary" className="bg-yellow-100 text-yellow-800">Pending</Badge>;
      case 'approved':
        return <Badge variant="secondary" className="bg-blue-100 text-blue-800">Approved</Badge>;
      case 'settled':
        return <Badge variant="secondary" className="bg-green-100 text-green-800">Settled</Badge>;
      case 'rejected':
        return <Badge variant="destructive">Rejected</Badge>;
      default:
        return <Badge variant="outline">{status}</Badge>;
    }
  };

  return (
    <div className="min-h-screen bg-background">
      <Header />
      <div className="flex">
        <Sidebar />
        <main className="flex-1 p-6">
          <div className="mb-8">
            <h1 className="text-3xl font-bold text-foreground mb-2" data-testid="text-profile-title">
              Uploader Profile
            </h1>
            <p className="text-muted-foreground" data-testid="text-profile-description">
              Track your uploads, earnings, and manage withdrawals
            </p>
          </div>

          {/* Stats Overview */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
            <Card data-testid="card-total-uploads">
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm font-medium text-muted-foreground">Total Uploads</p>
                    <p className="text-2xl font-bold text-foreground">
                      {uploaderStats?.totalUploads || 0}
                    </p>
                  </div>
                  <Upload className="h-8 w-8 text-primary" />
                </div>
              </CardContent>
            </Card>

            <Card data-testid="card-published-notes">
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm font-medium text-muted-foreground">Published Notes</p>
                    <p className="text-2xl font-bold text-green-600">
                      {uploaderStats?.publishedNotes || 0}
                    </p>
                  </div>
                  <FileText className="h-8 w-8 text-green-600" />
                </div>
              </CardContent>
            </Card>

            <Card data-testid="card-total-downloads">
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm font-medium text-muted-foreground">Total Downloads</p>
                    <p className="text-2xl font-bold text-blue-600">
                      {uploaderStats?.totalDownloads || 0}
                    </p>
                  </div>
                  <TrendingUp className="h-8 w-8 text-blue-600" />
                </div>
              </CardContent>
            </Card>

            <Card data-testid="card-wallet-balance">
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm font-medium text-muted-foreground">Wallet Balance</p>
                    <p className="text-2xl font-bold text-emerald-600 flex items-center">
                      <IndianRupee className="h-5 w-5 mr-1" />
                      {uploaderStats?.walletBalance || 0}
                    </p>
                  </div>
                  <Wallet className="h-8 w-8 text-emerald-600" />
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Wallet Section */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Withdrawal Request */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center">
                  <Wallet className="h-5 w-5 mr-2" />
                  Request Withdrawal
                </CardTitle>
              </CardHeader>
              <CardContent>
                <p className="text-sm text-muted-foreground mb-4">
                  Minimum withdrawal: ₹200 | Current balance: ₹{uploaderStats?.walletBalance || 0}
                </p>

                <Dialog open={withdrawalDialogOpen} onOpenChange={setWithdrawalDialogOpen}>
                  <DialogTrigger asChild>
                    <Button 
                      className="w-full"
                      disabled={!uploaderStats || uploaderStats.walletBalance < 200}
                      data-testid="button-request-withdrawal"
                    >
                      <IndianRupee className="h-4 w-4 mr-2" />
                      Request Withdrawal
                    </Button>
                  </DialogTrigger>
                  <DialogContent className="sm:max-w-md">
                    <DialogHeader>
                      <DialogTitle>Request Withdrawal</DialogTitle>
                    </DialogHeader>
                    <div className="space-y-4">
                      <div>
                        <label className="text-sm font-medium">
                          Amount (Minimum ₹200):
                        </label>
                        <Input
                          type="number"
                          value={withdrawalAmount}
                          onChange={(e) => setWithdrawalAmount(e.target.value)}
                          placeholder="Enter amount"
                          className="mt-2"
                          min="200"
                          max={uploaderStats?.walletBalance || 0}
                          data-testid="input-withdrawal-amount"
                        />
                      </div>

                      <div>
                        <label className="text-sm font-medium">Payment Method:</label>
                        <Select value={paymentMethod} onValueChange={setPaymentMethod}>
                          <SelectTrigger className="mt-2">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="upi">UPI</SelectItem>
                            <SelectItem value="bank">Bank Transfer</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>

                      {paymentMethod === "upi" ? (
                        <div>
                          <label className="text-sm font-medium">UPI ID:</label>
                          <Input
                            value={upiId}
                            onChange={(e) => setUpiId(e.target.value)}
                            placeholder="example@upi"
                            className="mt-2"
                            data-testid="input-upi-id"
                          />
                        </div>
                      ) : (
                        <div className="space-y-3">
                          <div>
                            <label className="text-sm font-medium">Account Holder Name:</label>
                            <Input
                              value={bankDetails.accountHolderName}
                              onChange={(e) => setBankDetails({...bankDetails, accountHolderName: e.target.value})}
                              placeholder="Full name as per bank"
                              className="mt-1"
                            />
                          </div>
                          <div>
                            <label className="text-sm font-medium">Account Number:</label>
                            <Input
                              value={bankDetails.accountNumber}
                              onChange={(e) => setBankDetails({...bankDetails, accountNumber: e.target.value})}
                              placeholder="Bank account number"
                              className="mt-1"
                            />
                          </div>
                          <div>
                            <label className="text-sm font-medium">IFSC Code:</label>
                            <Input
                              value={bankDetails.ifscCode}
                              onChange={(e) => setBankDetails({...bankDetails, ifscCode: e.target.value})}
                              placeholder="IFSC code"
                              className="mt-1"
                            />
                          </div>
                          <div>
                            <label className="text-sm font-medium">Bank Name:</label>
                            <Input
                              value={bankDetails.bankName}
                              onChange={(e) => setBankDetails({...bankDetails, bankName: e.target.value})}
                              placeholder="Bank name"
                              className="mt-1"
                            />
                          </div>
                        </div>
                      )}

                      <div className="flex justify-end space-x-2">
                        <Button
                          variant="outline"
                          onClick={() => setWithdrawalDialogOpen(false)}
                        >
                          Cancel
                        </Button>
                        <Button
                          onClick={handleWithdrawalSubmit}
                          disabled={withdrawalMutation.isPending || !withdrawalAmount}
                          className="bg-emerald-600 hover:bg-emerald-700"
                          data-testid="button-submit-withdrawal"
                        >
                          {withdrawalMutation.isPending ? "Submitting..." : "Submit Request"}
                        </Button>
                      </div>
                    </div>
                  </DialogContent>
                </Dialog>
              </CardContent>
            </Card>

            {/* Recent Withdrawal Requests */}
            <Card>
              <CardHeader>
                <CardTitle>Recent Withdrawal Requests</CardTitle>
              </CardHeader>
              <CardContent className="p-0">
                {withdrawalRequests?.length > 0 ? (
                  <div className="divide-y divide-border">
                    {withdrawalRequests.slice(0, 5).map((request: any) => (
                      <div 
                        key={request.id} 
                        className="p-4 hover:bg-accent transition-colors"
                        data-testid={`withdrawal-request-${request.id}`}
                      >
                        <div className="flex items-center justify-between mb-2">
                          <span className="font-medium flex items-center">
                            <IndianRupee className="h-4 w-4 mr-1" />
                            ₹{request.amount}
                          </span>
                          {getStatusBadge(request.status)}
                        </div>
                        <div className="text-sm text-muted-foreground">
                          {new Date(request.requestedAt).toLocaleDateString()}
                        </div>
                        {request.adminComments && (
                          <div className="text-sm text-blue-600 mt-1">
                            Admin: {request.adminComments}
                          </div>
                        )}
                        {request.rejectionReason && (
                          <div className="text-sm text-red-600 mt-1">
                            Rejected: {request.rejectionReason}
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-8" data-testid="empty-withdrawal-requests">
                    <Clock className="h-8 w-8 text-muted-foreground mx-auto mb-2 opacity-50" />
                    <p className="text-sm text-muted-foreground">No withdrawal requests yet</p>
                  </div>
                )}
              </CardContent>
            </Card>
          </div>
        </main>
      </div>
    </div>
  );
}

client/src/pages/exam-selection.tsx.content:
import { useState, useEffect } from "react";
import { useQuery } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { 
  ArrowLeft, 
  ArrowRight,
  Search,
  BookOpen,
  Trophy,
  Building2,
  GraduationCap,
  Star
} from "lucide-react";
import Header from "@/components/layout/header";
import Sidebar from "@/components/layout/sidebar";

// Category icons mapping
const categoryIcons = {
  school: BookOpen,
  competitive_exam: Trophy,
  professional_exam: Building2,
  college: GraduationCap
};

// Category titles mapping
const categoryTitles = {
  school: "Classes 9th–12th",
  competitive_exam: "Entrance Exams", 
  professional_exam: "Government Exams",
  college: "College Exams"
};

export default function ExamSelection() {
  const [, setLocation] = useLocation();
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedExam, setSelectedExam] = useState<string>("");

  // Get category from URL params
  const urlParams = new URLSearchParams(window.location.search);
  const categoryType = urlParams.get('category') || 'school';

  // Fetch educational categories for selected category type
  const { data: categories, isLoading } = useQuery<any[]>({
    queryKey: ['/api/educational-categories', categoryType],
    queryFn: async () => {
      const response = await fetch(`/api/educational-categories?categoryType=${categoryType}`);
      if (!response.ok) throw new Error("Failed to fetch categories");
      return response.json();
    },
  });

  // Filter categories based on search term
  const filteredCategories = categories?.filter(category =>
    category.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    category.description?.toLowerCase().includes(searchTerm.toLowerCase())
  ) || [];

  const handleExamSelect = (categoryId: string) => {
    setSelectedExam(categoryId);
  };

  const handleNext = () => {
    if (selectedExam) {
      // Navigate to catalog with selected exam category
      setLocation(`/catalog?categoryId=${selectedExam}`);
    }
  };

  const handleBack = () => {
    setLocation('/categories');
  };

  const IconComponent = categoryIcons[categoryType as keyof typeof categoryIcons] || BookOpen;
  const categoryTitle = categoryTitles[categoryType as keyof typeof categoryTitles] || "Select Exam";

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-purple-50 via-pink-50 to-cyan-50">
        <Header />
        <div className="flex">
          <Sidebar />
          <main className="flex-1 p-6 flex items-center justify-center">
            <div className="text-center">
              <div className="animate-spin w-12 h-12 border-4 border-primary border-t-transparent rounded-full mx-auto mb-4" />
              <p className="text-gray-600">Loading exam options...</p>
            </div>
          </main>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-50 via-pink-50 to-cyan-50">
      <Header />
      <div className="flex">
        <Sidebar />
        <main className="flex-1 p-6" role="main">
          {/* Header Section */}
          <div className="flex items-center justify-between mb-8">
            <Button
              variant="outline"
              onClick={handleBack}
              className="bg-white hover:bg-gray-50 shadow-sm border border-gray-200"
              data-testid="button-back-categories"
            >
              <ArrowLeft className="w-4 h-4 mr-2" />
              Back to Categories
            </Button>

            {selectedExam && (
              <Button 
                onClick={handleNext}
                className="bg-gradient-to-r from-purple-600 to-pink-600 text-white hover:shadow-lg transition-all duration-200 font-semibold px-6"
                data-testid="button-next-subjects"
              >
                Next: View Notes
                <ArrowRight className="ml-2 h-4 w-4" />
              </Button>
            )}
          </div>

          {/* Title Section */}
          <div className="text-center mb-12">
            <div className="flex justify-center mb-6">
              <div className="relative w-20 h-20 bg-gradient-to-br from-purple-500 via-pink-600 to-blue-600 rounded-2xl flex items-center justify-center shadow-2xl border-4 border-purple-400/30">
                <IconComponent className="h-10 w-10 text-white" />
              </div>
            </div>
            <h1 className="text-4xl font-bold bg-gradient-to-r from-purple-700 via-pink-600 to-blue-600 bg-clip-text text-transparent mb-4">
              {categoryTitle}
            </h1>
            <p className="text-gray-600 text-xl max-w-3xl mx-auto mb-6">
              Select your specific exam or class to access targeted study materials from top performers.
            </p>

            {/* Search Bar */}
            <div className="max-w-xl mx-auto relative mb-8">
              <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 h-5 w-5" />
              <Input
                type="text"
                placeholder="Search for specific exam or class..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-12 py-3 text-lg border-2 bg-white hover:border-purple-300 focus:border-purple-400 transition-colors shadow-sm"
                data-testid="input-search-exams"
              />
            </div>
          </div>

          {/* Selection Summary */}
          {selectedExam && (
            <div className="max-w-4xl mx-auto mb-8">
              <Card className="bg-purple-50 border-purple-200 border-2">
                <CardContent className="p-6">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 bg-gradient-to-r from-purple-500 to-pink-500 rounded-full flex items-center justify-center">
                        <Star className="h-6 w-6 text-white" />
                      </div>
                      <div>
                        <h3 className="text-lg font-semibold text-purple-800">Selected:</h3>
                        <p className="text-purple-600">
                          {categories?.find(cat => cat.id === selectedExam)?.name}
                        </p>
                      </div>
                    </div>
                    <Badge className="bg-gradient-to-r from-green-500 to-emerald-500 text-white">
                      ✓ Ready to Proceed
                    </Badge>
                  </div>
                </CardContent>
              </Card>
            </div>
          )}

          {/* Exam/Class Cards */}
          <div className="max-w-6xl mx-auto">
            {filteredCategories.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {filteredCategories.map((category, index) => (
                  <Card
                    key={category.id}
                    className={`cursor-pointer transition-all duration-300 hover:-translate-y-1 hover:shadow-xl border-2 ${
                      selectedExam === category.id
                        ? 'border-purple-400 bg-purple-50 shadow-lg'
                        : 'border-gray-200 bg-white hover:border-purple-300'
                    }`}
                    onClick={() => handleExamSelect(category.id)}
                    data-testid={`exam-card-${category.id}`}
                  >
                    <CardContent className="p-6">
                      <div className="flex items-start justify-between mb-4">
                        <div className="flex-1">
                          <h3 className={`text-lg font-bold mb-2 ${
                            selectedExam === category.id ? 'text-purple-700' : 'text-gray-800'
                          }`}>
                            {category.name}
                          </h3>
                          {category.description && (
                            <p className="text-gray-600 text-sm leading-relaxed mb-3">
                              {category.description}
                            </p>
                          )}
                        </div>
                        {category.icon && (
                          <div className="text-2xl ml-3">{category.icon}</div>
                        )}
                      </div>

                      {/* Category Details */}
                      <div className="space-y-2 mb-4">
                        {category.subjects && category.subjects.length > 0 && (
                          <div className="flex items-center gap-2 text-sm text-gray-500">
                            <BookOpen className="h-4 w-4" />
                            <span>{category.subjects.length} Subjects Available</span>
                          </div>
                        )}
                        {category.classLevel && (
                          <Badge variant="secondary" className="text-xs">
                            Class {category.classLevel}
                          </Badge>
                        )}
                        {category.board && (
                          <Badge variant="outline" className="text-xs">
                            {category.board}
                          </Badge>
                        )}
                      </div>

                      {/* Selection Indicator */}
                      <div className={`flex items-center justify-center py-2 px-4 rounded-lg transition-colors ${
                        selectedExam === category.id
                          ? 'bg-purple-100 text-purple-700 border border-purple-300'
                          : 'bg-gray-50 text-gray-600 hover:bg-purple-50'
                      }`}>
                        {selectedExam === category.id ? (
                          <>
                            <Star className="h-4 w-4 mr-2 fill-current" />
                            Selected
                          </>
                        ) : (
                          <>
                            Click to Select
                          </>
                        )}
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            ) : (
              <div className="text-center py-12">
                <Search className="h-16 w-16 mx-auto mb-4 text-gray-300" />
                <h3 className="text-xl font-semibold text-gray-600 mb-2">
                  {searchTerm ? 'No matching exams found' : 'No exams available'}
                </h3>
                <p className="text-gray-500">
                  {searchTerm 
                    ? 'Try adjusting your search terms' 
                    : 'Exam options for this category will be available soon'
                  }
                </p>
                {searchTerm && (
                  <Button 
                    variant="outline" 
                    className="mt-4"
                    onClick={() => setSearchTerm("")}
                  >
                    Clear Search
                  </Button>
                )}
              </div>
            )}
          </div>

          {/* Bottom Action */}
          {selectedExam && filteredCategories.length > 0 && (
            <div className="text-center mt-12">
              <Button 
                onClick={handleNext}
                size="lg"
                className="bg-gradient-to-r from-purple-600 to-pink-600 text-white hover:shadow-xl transition-all duration-200 font-semibold px-8 py-4 text-lg"
                data-testid="button-proceed-to-notes"
              >
                Proceed to Study Materials
                <ArrowRight className="ml-2 h-5 w-5" />
              </Button>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

